    {
      "principle": "other: cost-benefit business pragmatism",
      "turn": 1,
      "quote": "can lead to negative reviews or chargebacks that cost far more than a single speaker",
      "use": "stretched",
      "note": "It considers the seller’s practical costs, but those costs do not establish that the customer’s inaccurate claim was morally acceptable."
    }
  ],
